CREATE OR REPLACE FUNCTION public.guard_income_category_review() RETURNS trigger LANGUAGE plpgsql SET search_path = public, pg_temp AS $$ BEGIN IF TG_OP = 'UPDATE' THEN IF OLD.verification_status <> 'pending' AND (NEW.category_id IS DISTINCT FROM OLD.category_id OR NEW.suggested_category_id IS DISTINCT FROM OLD.suggested_category_id OR NEW.suggestion_revision IS DISTINCT FROM OLD.suggestion_revision OR NEW.category_confirmed_at IS DISTINCT FROM OLD.category_confirmed_at OR NEW.category_confirmed_by IS DISTINCT FROM OLD.category_confirmed_by OR NEW.category_decision_id IS DISTINCT FROM OLD.category_decision_id) THEN RAISE EXCEPTION 'income_category_locked' USING ERRCODE='23514'; END IF; IF NEW.verification_status = 'verified' AND OLD.verification_status = 'pending' AND (OLD.category_confirmed_at IS NULL OR (OLD.suggestion_revision IS NOT NULL AND OLD.category_confirmed_at < OLD.suggested_at)) THEN RAISE EXCEPTION 'income_category_review_required' USING ERRCODE='23514'; END IF; END IF; RETURN NEW; END $$;
REVOKE INSERT ON public.society_income_records FROM authenticated;
COMMENT ON COLUMN public.society_income_records.category_confirmed_at IS 'Human-reviewed category decision required before pending income is verified; historic records remain unchanged.';